/** What a run is played against: tiers, battle conditions, enemies, perks and tournaments. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { bullets, heading, recordTable, sections, table } from '../render.mjs'

export function build(context) {
  const { data } = context.sdk
  const { format } = context

  context.page(
    'Tiers',
    sections(
      bullets(data.TIER_OVERVIEW_FACTS),
      table(
        ['Tier', 'Coin bonus', 'Unlocks at', 'Battle conditions'],
        data.TIER_DATA.map(tier => [
          tier.tier,
          `x${format.value(tier.coinBonus)}`,
          tier.requiredPreviousTier === null ? '' : `Tier ${tier.requiredPreviousTier}, wave ${tier.requiredWave}`,
          tier.battleConditions.map(condition => condition.raw).join(', '),
        ]),
      ),
      `See also ${context.link('Battle Conditions')}.`,
    ),
    { source: ['TIER_DATA', 'TIER_OVERVIEW_FACTS'] },
  )

  context.page(
    'Battle Conditions',
    sections(
      table(['Battle condition', 'What it does'], data.TIER_BATTLE_CONDITION_DEFINITIONS.map(item => [item.name, item.description])),
      heading(2, 'Level By Tier'),
      recordTable(data.TIER_BATTLE_CONDITION_ROWS, format, ['tier', ['name', 'Battle condition'], 'level']),
      `Back to ${context.link('Tiers')}.`,
    ),
    { source: ['TIER_BATTLE_CONDITION_DEFINITIONS', 'TIER_BATTLE_CONDITION_ROWS'] },
  )

  context.page(
    'Enemies',
    sections(
      bullets(data.ENEMIES_OVERVIEW_FACTS),
      heading(2, 'Enemy Types'),
      table(['Enemy', 'Summary'], data.ENEMY_TYPE_SUMMARIES.map(enemy => [enemy.name, enemy.summary])),
      heading(2, 'Normal Enemies And Bosses'),
      bullets(data.NORMAL_AND_BOSS_ENEMY_FACTS),
      heading(3, 'Boss Waves'),
      recordTable(data.BOSS_WAVE_SPAWN_ROWS, format),
      heading(2, 'Elite Enemies'),
      bullets(data.ELITE_ENEMY_FACTS),
      heading(3, 'Elite Cells By Tier'),
      bullets(data.ELITE_CELL_TIER_FACTS),
      recordTable(data.ELITE_CELL_TIER_ROWS, format),
      heading(2, 'Fleet Enemies'),
      bullets([...data.FLEET_ENEMY_FACTS, ...data.FLEET_ENEMY_TYPE_FACTS]),
      heading(3, 'Fleet Spawns'),
      recordTable(data.FLEET_SPAWN_ROWS, format),
      heading(3, 'Fleet Rewards'),
      recordTable(data.FLEET_REWARD_ROWS, format),
      heading(2, 'Enemy Labs'),
      bullets(data.ENEMY_LAB_FACTS),
    ),
    { source: ['ENEMY_TYPE_SUMMARIES', 'FLEET_SPAWN_ROWS', 'FLEET_REWARD_ROWS', 'ELITE_CELL_TIER_ROWS'] },
  )

  const perkTable = perks => table(['Perk', 'Times it can be taken'], perks.map(perk => [perk.perk, perk.quantity]))
  context.page(
    'Perks',
    sections(
      bullets(data.PERK_OVERVIEW_FACTS),
      heading(2, 'Choosing Perks'),
      bullets(data.PERK_CHOICE_FACTS),
      recordTable(data.PERK_POOL_RATES, format),
      heading(2, 'Standard Perks'),
      perkTable(data.STANDARD_PERKS),
      bullets([...data.STANDARD_PERK_MATH_FACTS, ...data.STANDARD_PERK_NOTES]),
      heading(2, 'Ultimate Weapon Perks'),
      perkTable(data.UW_PERKS),
      bullets([...data.UW_PERK_NOTES, ...data.RANDOM_UW_PERK_NOTES]),
      recordTable(data.RANDOM_UW_PERK_STATS, format),
      heading(2, 'Trade-Off Perks'),
      perkTable(data.TRADE_OFF_PERKS),
      bullets(data.TRADE_OFF_PERK_NOTES),
      heading(2, data.PERK_WAVE_REQUIREMENT_FORMULA.name),
      `\`${data.PERK_WAVE_REQUIREMENT_FORMULA.formula}\``,
      bullets(data.PERK_WAVE_REQUIREMENT_FORMULA.notes),
      recordTable(data.PERK_WAVE_REQUIREMENT_BRACKETS, format),
      heading(2, 'Perk Labs'),
      recordTable(data.PERK_LABS, format, [['name', 'Lab'], 'levels', ['unlockRequirement', 'Unlocks at'], ['behavior', 'What it does']]),
    ),
    { source: ['ALL_PERKS', 'PERK_POOL_RATES', 'PERK_LABS', 'PERK_WAVE_REQUIREMENT_FORMULA'] },
  )

  context.page(
    'Tournaments',
    sections(
      bullets(data.TOURNAMENT_OVERVIEW_FACTS),
      heading(2, 'Entering'),
      bullets([...data.TOURNAMENT_ENTRY_FACTS, ...data.TOURNAMENT_TICKET_FACTS]),
      table(['Starts on', 'Time (UTC)'], data.TOURNAMENT_SCHEDULE.map(slot => [slot.day, slot.startUtc])),
      heading(2, 'Leagues'),
      recordTable(data.TOURNAMENT_LEAGUES, format, ['league', ['playerCount', 'Players'], ['rewardCurrencies', 'Rewards']]),
      heading(2, 'Promotion And Demotion'),
      bullets(data.TOURNAMENT_PROMOTION_FACTS),
      recordTable(data.TOURNAMENT_PROMOTION_RULES, format, [
        'league',
        ['promotedRankMax', 'Promoted up to rank'],
        'promotesTo',
        ['demotedRankMin', 'Demoted from rank'],
        'demotesTo',
      ]),
      heading(2, 'Difficulty And Heat'),
      bullets([...data.TOURNAMENT_DIFFICULTY_FACTS, ...data.TOURNAMENT_HEAT_FACTS]),
      recordTable(data.TOURNAMENT_HEAT_PROFILES, format),
      heading(2, 'Rewards'),
      data.TOURNAMENT_REWARD_RULE_FACT,
      ...data.TOURNAMENT_REWARD_TABLES.map(league =>
        sections(heading(3, league.league), recordTable(league.rewards, format, ['rank', 'gems', 'stones', 'keys'])),
      ),
    ),
    { source: ['TOURNAMENT_LEAGUES', 'TOURNAMENT_REWARD_TABLES', 'TOURNAMENT_HEAT_PROFILES', 'TOURNAMENT_PROMOTION_RULES'] },
  )

  context.group('Runs', ['Tiers', 'Battle Conditions', 'Enemies', 'Perks', 'Tournaments'])
}
